// ── Event loop ordering quiz ──────────────────────────────────
console.log('1 - synchronous');

setTimeout(() => console.log('2 - setTimeout (task)'), 0);

Promise.resolve()
  .then(() => console.log('3 - Promise.then (microtask)'))
  .then(() => console.log('4 - chained .then (microtask)'));

queueMicrotask(() => console.log('5 - queueMicrotask'));

console.log('6 - synchronous');

// Output order: 1, 6, 3, 5, 4, 2
// Explanation:
//  1, 6  → synchronous code runs first (call stack)
//  3, 5, 4 → microtasks drained (Promise.then, queueMicrotask)
//  2   → setTimeout callback (next task queue item)

// ── async/await desugared to understand timing ────────────────
async function fetchUser(id) {
  // await yields control; continuation is a microtask
  const res = await fetch(`/api/users/${id}`);
  const data = await res.json();
  return data; // resolved value of the returned Promise
}

// Equivalent using raw Promises:
function fetchUserRaw(id) {
  return fetch(`/api/users/${id}`)
    .then(res => res.json());
}

// ── Avoiding main thread blocking with chunking ───────────────
async function processLargeArray(items) {
  const CHUNK_SIZE = 100;
  const results = [];

  for (let i = 0; i < items.length; i += CHUNK_SIZE) {
    const chunk = items.slice(i, i + CHUNK_SIZE);

    // Process chunk synchronously
    for (const item of chunk) {
      results.push(item * 2); // example work
    }

    // Yield to event loop: allow rendering + other tasks
    await new Promise(resolve => setTimeout(resolve, 0));
  }

  return results;
}

// ── requestAnimationFrame: sync with render frames ────────────
let animating = false;
let offset = 0;

function startAnimation(el) {
  animating = true;
  function frame() {
    if (!animating) return;
    offset += 2;
    el.style.transform = `translateX(${offset}px)`;
    requestAnimationFrame(frame); // schedule next frame
  }
  requestAnimationFrame(frame);
}

console.log('Event loop examples loaded — check console output order above');

// ── Queue priority summary ────────────────────────────────────
//
// Priority (highest to lowest):
//  1. Call Stack       — currently executing code
//  2. Microtask Queue  — Promise.then, queueMicrotask, MutationObserver
//                        ALL drained before next task
//  3. Animation Frame  — requestAnimationFrame callbacks (before render)
//  4. Render           — layout, paint, composite (browser internal)
//  5. Task Queue       — setTimeout, setInterval, I/O events, click handlers
//                        ONE task per loop iteration

// ── Sources of tasks vs microtasks ───────────────────────────
const TASKS = [
  'setTimeout(fn, ms)',
  'setInterval(fn, ms)',
  'I/O events (click, keydown, fetch response)',
  'MessageChannel.postMessage()',
  'setImmediate() — Node.js only',
];

const MICROTASKS = [
  'Promise.then() / .catch() / .finally()',
  'queueMicrotask(fn)',
  'MutationObserver callback',
  'await (continuation of async function)',
];

// ── Common event loop traps ───────────────────────────────────

// TRAP 1: setTimeout(fn, 0) does NOT mean immediate
// It means "put fn in the task queue after at least 0ms"
// Microtasks from the current task run first

// TRAP 2: Infinite microtask loop blocks rendering
async function infiniteLoop() {
  while (true) {
    await Promise.resolve(); // keeps adding microtasks, never renders!
  }
}
// Use setTimeout to give the renderer a chance

// TRAP 3: Blocking the main thread
// This freezes the UI for 5 seconds:
function blockingWork() {
  const end = Date.now() + 5000;
  while (Date.now() < end) { /* busy wait */ }
}
// Solution: Web Worker or chunked async processing

// TRAP 4: Unhandled Promise rejections
Promise.reject(new Error('oops'));
// Always attach .catch() or use try/catch in async functions
// window.addEventListener('unhandledrejection', e => ...);
